export async function maybeDisplayProgressSurvey(
  milestone: "dossier_completed" | "draft_exported",
): Promise<void> {
  const surveyName = optionalString(
    import.meta.env.PUBLIC_POSTHOG_PROGRESS_SURVEY_NAME as string | undefined,
  );
