import { wordPressRewriteRules } from '@wp-playground/wordpress';

import { reportServiceWorkerMetrics } from '@php-wasm/logger';

import {

cacheFirstFetch,

networkFirstFetch,

cacheOfflineModeAssetsForCurrentRelease,

isCurrentServiceWorkerActive,

purgeEverythingFromPreviousRelease,

shouldCacheUrl,

} from './src/lib/offline-mode-cache';

import {

getRemoteAccessRelayMapping,

getRemoteAccessRelayMappingFromUrl,

handleRemoteAccessRelayMessage,

handleRemoteAccessRelayProbe,

handleRemoteAccessRelayRequest,

} from '@wp-playground/remote-access';

if (!(self as any).document) {

// Workaround: vite translates import.meta.url

// to document.currentScript which fails inside of

// a service worker because document is undefined

// @ts-ignore

// eslint-disable-next-line no-global-assign

self.document = {};

}

self.addEventListener('message', (event) => {

handleRemoteAccessRelayMessage(event);

