import {
  OFFLINE_CACHE_PREFIX,
  OFFLINE_SHELL_CACHE,
  OFFLINE_STATIC_CACHE,
  OPTIONAL_OFFLINE_STATIC_PATHS,
  REQUIRED_OFFLINE_SHELLS,
  canStorePublicResponse,
  offlineShellPath,
  shouldCacheStaticRequest,
} from "../utils/offline-cache-policy";

const worker = globalThis as unknown as ServiceWorkerGlobalScope;
const refreshedShells = new Set<string>();

function anonymousRequest(path: string, accept: string): Request {
  return new Request(new URL(path, worker.location.origin), {
    cache: "reload",
    credentials: "omit",
    headers: { Accept: accept },
  });
}

async function fetchAndStore(
  cache: Cache,
  request: Request,
): Promise<Response> {
  const response = await fetch(request);
  if (canStorePublicResponse(response)) {
    await cache.put(request, response.clone());
  }
  return response;
}

async function fetchShellAndStore(cache: Cache, path: string): Promise<void> {
  const request = anonymousRequest(path, "text/html");
  const response = await fetch(request);
  const contentType = response.headers.get("content-type") ?? "";
  if (!canStorePublicResponse(response) || !contentType.includes("text/html")) {
    throw new Error(`Offline shell ${path} did not return cacheable HTML`);
  }
  await cache.put(request, response);
}

async function refreshAnonymousShell(path: string): Promise<void> {
  if (refreshedShells.has(path)) return;
  refreshedShells.add(path);
  try {
    const cache = await caches.open(OFFLINE_SHELL_CACHE);
    await fetchShellAndStore(cache, path);
  } catch {
    // Being offline is expected. Permit another refresh attempt later in this
    // worker lifetime instead of pinning a failed attempt.
    refreshedShells.delete(path);
  }
}

async function networkFirstShell(
  request: Request,
  canonicalPath: string,
): Promise<Response> {
  try {
    return await fetch(request);
  } catch (error) {
    const cache = await caches.open(OFFLINE_SHELL_CACHE);
    const cached = await cache.match(
      anonymousRequest(canonicalPath, "text/html"),
      { ignoreVary: true },
    );
    if (cached) return cached;
    throw error;
  }
}

async function cacheFirstBuildAsset(request: Request): Promise<Response> {
  const cache = await caches.open(OFFLINE_STATIC_CACHE);
  const cached = await cache.match(request);
  if (cached) return cached;
  return fetchAndStore(cache, request);
}

async function revalidateStaticAsset(request: Request): Promise<Response> {
  const cache = await caches.open(OFFLINE_STATIC_CACHE);
  return fetchAndStore(cache, request);
}

async function cachedStaticAsset(
  request: Request,
  update: Promise<Response>,
): Promise<Response> {
  const cache = await caches.open(OFFLINE_STATIC_CACHE);
  return (await cache.match(request)) ?? update;
}

worker.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const shellCache = await caches.open(OFFLINE_SHELL_CACHE);
      // The worker must not replace a known-good version unless its two core
      // anonymous shells are available. This leaves the active worker intact
      // when an update is installed over a flaky connection.
      await Promise.all(
        REQUIRED_OFFLINE_SHELLS.map((path) =>
          fetchShellAndStore(shellCache, path),
        ),
      );

      const staticCache = await caches.open(OFFLINE_STATIC_CACHE);
      await Promise.allSettled(
        OPTIONAL_OFFLINE_STATIC_PATHS.map((path) =>
          fetchAndStore(staticCache, anonymousRequest(path, "*/*")),
        ),
      );
    })(),
  );
});

worker.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names
          .filter(
            (name) =>
              name.startsWith(OFFLINE_CACHE_PREFIX) &&
              name !== OFFLINE_SHELL_CACHE &&
              name !== OFFLINE_STATIC_CACHE,
          )
          .map((name) => caches.delete(name)),
      );
      await worker.clients.claim();
    })(),
  );
});

worker.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== worker.location.origin) return;

  const shellPath = offlineShellPath(url.pathname);
  if (request.mode === "navigate" && shellPath) {
    event.respondWith(networkFirstShell(request, shellPath));
    event.waitUntil(refreshAnonymousShell(shellPath));
    return;
  }

  if (shouldCacheStaticRequest(request, url, worker.location.origin)) {
    // Qwik build chunks are content-addressed. Public assets with stable names
    // revalidate in the background so a later deployment is not pinned by an
    // old logo, manifest, or font.
    if (url.pathname.startsWith("/build/")) {
      event.respondWith(cacheFirstBuildAsset(request));
      return;
    }

    const update = revalidateStaticAsset(request);
    event.waitUntil(update.then(() => undefined).catch(() => undefined));
    event.respondWith(cachedStaticAsset(request, update));
  }
});
export const OFFLINE_CACHE_PREFIX = "twyne-offline-";
export const OFFLINE_CACHE_VERSION = "v2";
export const OFFLINE_SHELL_CACHE = `${OFFLINE_CACHE_PREFIX}${OFFLINE_CACHE_VERSION}-shell`;
export const OFFLINE_STATIC_CACHE = `${OFFLINE_CACHE_PREFIX}${OFFLINE_CACHE_VERSION}-static`;

/**
 * These routes render a content-free application shell. Manuscripts and other
 * writer data remain in IndexedDB/Lix; no route response containing that data
 * belongs in Cache Storage.
 */
const WRITING_SHELL_PATHS = new Set([
  "/analysis/",
  "/apparatus/",
  "/desk/",
  "/dossier/create/",
  "/dossier/refine/",
  "/editor/",
  "/library/",
  "/onboarding/",
  "/personas/",
  "/revisions/",
  "/rubric/",
  "/settings/",
]);

export const REQUIRED_OFFLINE_SHELLS = ["/editor/", "/dossier/create/"];

export const OPTIONAL_OFFLINE_STATIC_PATHS = [
  "/manifest.json",
  "/assets/griffin-mark.svg",
  "/icon-192.png",
  "/icon-512.png",
  "/icon-512-maskable.png",
];

const STATIC_ROOT_PATHS = new Set([
  "/apple-touch-icon.png",
  "/favicon.ico",
  "/favicon.svg",
  "/icon-192.png",
  "/icon-512.png",
  "/icon-512-maskable.png",
  "/manifest.json",
  "/og-image.png",
  "/twyne-wordmark.svg",
]);

function withTrailingSlash(pathname: string): string {
  return pathname.endsWith("/") ? pathname : `${pathname}/`;
}

export function offlineShellPath(pathname: string): string | undefined {
  const canonical = withTrailingSlash(pathname);
  return WRITING_SHELL_PATHS.has(canonical) ? canonical : undefined;
}

/**
 * Only files produced by the client build or checked into public assets may be
 * cached at runtime. Request destination is intentionally not trusted: an API
 * can return an image or script while still containing private/user data.
 */
export function isCacheableStaticUrl(url: URL, appOrigin: string): boolean {
  if (url.origin !== appOrigin) return false;
  return (
    url.pathname.startsWith("/build/") ||
    url.pathname.startsWith("/assets/") ||
    STATIC_ROOT_PATHS.has(url.pathname)
  );
}

export function hasSensitiveRequestHeaders(request: Request): boolean {
  return (
    request.headers.has("authorization") ||
    request.headers.has("range") ||
    request.headers.has("x-qwik-fullpath") ||
    request.headers.has("x-qwik-route-path")
  );
}

export function shouldCacheStaticRequest(
  request: Request,
  url: URL,
  appOrigin: string,
): boolean {
  return (
    request.method === "GET" &&
    !hasSensitiveRequestHeaders(request) &&
    isCacheableStaticUrl(url, appOrigin)
  );
}

export function canStorePublicResponse(response: Response): boolean {
  if (
    !response.ok ||
    response.status === 206 ||
    response.type === "opaque" ||
    response.redirected
  ) {
    return false;
  }

  const cacheControl = response.headers.get("cache-control") ?? "";
  if (/(?:^|,)\s*(?:no-store|private)\b/i.test(cacheControl)) return false;

  const vary = response.headers.get("vary") ?? "";
  if (/(?:^|,)\s*(?:\*|cookie|authorization)\s*(?:,|$)/i.test(vary)) {
    return false;
  }

  return (
    !response.headers.has("set-cookie") &&
    !response.headers.has("content-range")
  );
}
import { describe, expect, test } from "bun:test";
import {
  canStorePublicResponse,
  isCacheableStaticUrl,
  offlineShellPath,
  shouldCacheStaticRequest,
} from "./offline-cache-policy";

const ORIGIN = "https://twyne.example";

describe("offline application shells", () => {
  test("recognises writing routes with or without their trailing slash", () => {
    expect(offlineShellPath("/editor")).toBe("/editor/");
    expect(offlineShellPath("/editor/")).toBe("/editor/");
    expect(offlineShellPath("/dossier/create/")).toBe("/dossier/create/");
  });

  test("never treats public, auth, API, or loader routes as an offline shell", () => {
    expect(offlineShellPath("/@alice/draft/")).toBeUndefined();
    expect(offlineShellPath("/auth/callback/")).toBeUndefined();
    expect(offlineShellPath("/api/tinker/models/")).toBeUndefined();
    expect(
      offlineShellPath("/editor/q-loader-private.hash.json"),
    ).toBeUndefined();
  });
});

describe("offline static asset policy", () => {
  test("allows only same-origin build and public asset URLs", () => {
    expect(
      isCacheableStaticUrl(new URL("/build/q-abc.js", ORIGIN), ORIGIN),
    ).toBe(true);
    expect(
      isCacheableStaticUrl(new URL("/assets/editor.css", ORIGIN), ORIGIN),
    ).toBe(true);
    expect(
      isCacheableStaticUrl(new URL("/manifest.json", ORIGIN), ORIGIN),
    ).toBe(true);
    expect(
      isCacheableStaticUrl(new URL("https://cdn.example/font.woff2"), ORIGIN),
    ).toBe(false);
    expect(
      isCacheableStaticUrl(new URL("/api/image/private", ORIGIN), ORIGIN),
    ).toBe(false);
  });

  test("rejects authenticated, ranged, and Qwik loader requests", () => {
    const sensitiveHeaders: Array<Record<string, string>> = [
      { Authorization: "Bearer secret" },
      { Range: "bytes=0-20" },
      { "X-Qwik-fullpath": "/editor/" },
      { "X-Qwik-route-path": "/editor/" },
    ];
    for (const headers of sensitiveHeaders) {
      const request = new Request(`${ORIGIN}/build/q-abc.js`, { headers });
      expect(
        shouldCacheStaticRequest(request, new URL(request.url), ORIGIN),
      ).toBe(false);
    }
  });

  test("rejects mutations even when their URL resembles a static asset", () => {
    const request = new Request(`${ORIGIN}/assets/upload.png`, {
      method: "POST",
      body: "private bytes",
    });
    expect(
      shouldCacheStaticRequest(request, new URL(request.url), ORIGIN),
    ).toBe(false);
  });
});

describe("public response policy", () => {
  test("stores an ordinary public response", () => {
    expect(
      canStorePublicResponse(
        new Response("asset", {
          headers: { "Cache-Control": "public, max-age=31536000" },
        }),
      ),
    ).toBe(true);
  });

  test("rejects private and explicitly uncacheable responses", () => {
    for (const cacheControl of ["private", "no-store", "max-age=0, private"]) {
      expect(
        canStorePublicResponse(
          new Response("private", {
            headers: { "Cache-Control": cacheControl },
          }),
        ),
      ).toBe(false);
    }
  });

  test("rejects cookie-varying, authorised, partial, and failed responses", () => {
    expect(
      canStorePublicResponse(
        new Response("private", { headers: { Vary: "Accept, Cookie" } }),
      ),
    ).toBe(false);
    expect(
      canStorePublicResponse(
        new Response("private", { headers: { Vary: "Authorization" } }),
      ),
    ).toBe(false);
    expect(
      canStorePublicResponse(
        new Response("partial", {
          status: 206,
          headers: { "Content-Range": "bytes 0-6/20" },
        }),
      ),
    ).toBe(false);
    expect(
      canStorePublicResponse(new Response("missing", { status: 404 })),
    ).toBe(false);
  });
});

